App.register({group:'assets',label:'07 / 数字资产',routes:[{path:'assets/library',title:'资产中心',icon:'▧',permission:'assets',render(){const list=DB.assets.filter(a=>a.tenant===DB.state.tenant&&(DB.state.identity!=='employee'||a.owner===DB.identities.find(i=>i.role==='employee').user));return UI.page('DIGITAL ASSET / LIBRARY','数字资产中心','统一管理剧本、人物、场景、分镜、视频、音频与成片资产，保留版本和归属关系。',UI.btn('查看项目档案','go:workspace/projects','btn'),`<div class="grid grid-4">${UI.metric('当前租户资产',list.length,'仅展示当前租户范围','▧')}${UI.metric('人物 / 场景','12','可复用视觉身份档案','♙')}${UI.metric('音视频素材','48','关联镜头生产单元','♫')}${UI.metric('正式成片','6','按交付记录统计','▶')}</div><div class="card section-gap"><div class="toolbar"><div class="toolbar-left"><b class="small">资产目录</b><select class="field" style="width:auto"><option>全部类型</option><option>人物设定</option><option>场景设定</option><option>分镜</option><option>音频</option><option>成片</option></select></div><input class="search" data-filter placeholder="搜索资产名称 / 编号"></div>${UI.table(['资产名称','类型','来源项目','版本','创建者','更新时间','归属'],list.map(a=>`<tr data-search="${a.name} ${a.id}"><td><div class="entity"><div class="entity-mark">${a.type.slice(0,1)}</div><div><div class="entity-name">${a.name}</div><div class="entity-meta mono">${a.id}</div></div></div></td><td>${a.type}</td><td>${a.project}</td><td class="mono">${a.version}</td><td>${a.owner}</td><td>${a.date}</td><td>${UI.tag('当前租户','green')}</td></tr>`))}</div><div class="notice section-gap">资产复用遵循租户边界。跨租户引用需要明确授权，不因企业级汇总权限自动获得素材读取或修改权。</div>`);}}]});
